<?php $pageTitle='Frequently asked questions | RoomShift';$pageMeta='Answers to common questions about planning a RoomShift move.';include __DIR__.'/includes/header.php';$result=web_catalog(static fn()=>web_cms()->listFaqs(['limit'=>100]));include __DIR__.'/includes/navbar.php';$faqs=$result['items']??[]; ?><main class="container section-space"><header class="page-heading"><p class="eyebrow">Helpful answers</p><h1>Frequently asked questions</h1></header><?php if($GLOBALS['webDataError']): ?><div class="alert alert-warning"><?= e($t('error')) ?></div><?php elseif(!$faqs): ?><div class="empty-panel"><?= e($t('empty')) ?></div><?php else: ?><div class="accordion" id="faqList"><?php foreach($faqs as $i=>$faq): $id='faq'.(int)$faq['id']; ?><article class="accordion-item"><h2 class="accordion-header"><button class="accordion-button <?= $i?'collapsed':'' ?>" type="button" data-bs-toggle="collapse" data-bs-target="#<?= e($id) ?>" aria-expanded="<?= $i?'false':'true' ?>" aria-controls="<?= e($id) ?>"><?= e($faq['question']) ?></button></h2><div id="<?= e($id) ?>" class="accordion-collapse collapse <?= $i?'':'show' ?>" data-bs-parent="#faqList"><div class="accordion-body"><?= nl2br(e($faq['answer'])) ?></div></div></article><?php endforeach; ?></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';
